"""Derive one analytics row per team and season from validated team-game rows."""
from __future__ import annotations
import hashlib,json,os
from collections import defaultdict
from pathlib import Path
from cfb_analytics.raw.audit import discover_partitions
from cfb_analytics.derived.games import derived_game_partition_dir
SEASON_SCHEMA_VERSION="team-season-v7-tfl"
def derived_season_dir(root:Path,season:int)->Path:return root/"derived"/"seasons"/f"season={season}"
def _atomic(path:Path,data:bytes):path.parent.mkdir(parents=True,exist_ok=True);tmp=path.with_suffix(path.suffix+".tmp");tmp.write_bytes(data);os.replace(tmp,path)
def _sha(b:bytes)->str:return hashlib.sha256(b).hexdigest()
def _sum(rows,key):return sum((r.get(key) or 0) for r in rows)
def _rate(n,d):return n/d if d else None
def derive_team_seasons(team_games,season):
 grouped=defaultdict(list)
 for r in team_games:
  if r.get("season")==season:grouped[r["team"]].append(r)
 out=[]
 for team,rows in sorted(grouped.items()):
  games=len(rows);poss=_sum(rows,"validatedPossessions");dposs=_sum(rows,"validatedDefensivePossessions");plays=_sum(rows,"offensivePlays");dplays=_sum(rows,"defensivePlays");yards=_sum(rows,"offensiveYards");dyards=_sum(rows,"defensiveYardsAllowed");review=_sum(rows,"reviewPossessionGroups");review_games=sum(r.get("gameValidationStatus")!="PASS" for r in rows)
  row={"season":season,"team":team,"games":games,"validatedPossessions":poss,"validatedDefensivePossessions":dposs,"offensivePlays":plays,"defensivePlays":dplays,"offensiveYards":yards,"defensiveYardsAllowed":dyards,"yardsPerGame":_rate(yards,games),"yardsAllowedPerGame":_rate(dyards,games),"yardsPerPlay":_rate(yards,plays),"yardsAllowedPerPlay":_rate(dyards,dplays),"yardsPerPossession":_rate(yards,poss),"yardsAllowedPerPossession":_rate(dyards,dposs),"possessionsPerGame":_rate(poss,games),"defensivePossessionsPerGame":_rate(dposs,games),"reviewPossessionGroups":review,"reviewGames":review_games,"seasonValidationStatus":"PASS" if review_games==0 else "REVIEW","seasonSchemaVersion":SEASON_SCHEMA_VERSION}
  success_pairs=[("successEligiblePlays","successfulPlays","successRate"),("successEligiblePlaysAllowed","successfulPlaysAllowed","successRateAllowed")]
  for fam in ("rush","pass"):success_pairs += [(f"{fam}SuccessEligiblePlays",f"{fam}SuccessfulPlays",f"{fam}SuccessRate"),(f"{fam}SuccessEligiblePlaysAllowed",f"{fam}SuccessfulPlaysAllowed",f"{fam}SuccessRateAllowed")]
  for d in (1,2,3,4):success_pairs += [(f"down{d}SuccessEligiblePlays",f"down{d}SuccessfulPlays",f"down{d}SuccessRate"),(f"down{d}SuccessEligiblePlaysAllowed",f"down{d}SuccessfulPlaysAllowed",f"down{d}SuccessRateAllowed")]
  for eligible,successful,rate in success_pairs:e=_sum(rows,eligible);s=_sum(rows,successful);row[eligible]=e;row[successful]=s;row[rate]=_rate(s,e)
  explosive_pairs=[("explosiveEligiblePlays","explosivePlays","explosivePlayRate"),("explosiveEligiblePlaysAllowed","explosivePlaysAllowed","explosivePlayRateAllowed")]
  for fam in ("rush","pass"):explosive_pairs += [(f"{fam}ExplosiveEligiblePlays",f"{fam}ExplosivePlays",f"{fam}ExplosivePlayRate"),(f"{fam}ExplosiveEligiblePlaysAllowed",f"{fam}ExplosivePlaysAllowed",f"{fam}ExplosivePlayRateAllowed")]
  for eligible,explosive,rate in explosive_pairs:e=_sum(rows,eligible);x=_sum(rows,explosive);row[eligible]=e;row[explosive]=x;row[rate]=_rate(x,e)
  for fam in ("", "rush", "pass"):
   yk=f"{fam}SuccessfulPlayYards" if fam else "successfulPlayYards";sk=f"{fam}SuccessfulPlays" if fam else "successfulPlays";rk=f"{fam}YardsPerSuccessfulPlay" if fam else "yardsPerSuccessfulPlay";row[yk]=_sum(rows,yk);row[rk]=_rate(row[yk],row[sk]);ay=f"{fam}SuccessfulPlayYardsAllowed" if fam else "successfulPlayYardsAllowed";as_=f"{fam}SuccessfulPlaysAllowed" if fam else "successfulPlaysAllowed";ar=f"{fam}YardsPerSuccessfulPlayAllowed" if fam else "yardsPerSuccessfulPlayAllowed";row[ay]=_sum(rows,ay);row[ar]=_rate(row[ay],row[as_])
  for suffix in ("","Allowed"):
   if suffix:opp="scoringOpportunitiesAllowed";td="opportunityTouchdownsAllowed";fg="opportunityFieldGoalsAllowed";empty="emptyOpportunitiesForced";other="otherScoringOpportunitiesAllowed";resolved="resolvedPointOpportunitiesAllowed";unresolved="unresolvedPointOpportunitiesAllowed";pts="opportunityPointsAllowed";pp="pointsPerOpportunityAllowed";tdr="touchdownRatePerOpportunityAllowed";fgr="fieldGoalRatePerOpportunityAllowed";er="emptyRatePerOpportunityAllowed"
   else:opp="scoringOpportunities";td="opportunityTouchdowns";fg="opportunityFieldGoals";empty="emptyOpportunities";other="otherScoringOpportunities";resolved="resolvedPointOpportunities";unresolved="unresolvedPointOpportunities";pts="opportunityPoints";pp="pointsPerOpportunity";tdr="touchdownRatePerOpportunity";fgr="fieldGoalRatePerOpportunity";er="emptyRatePerOpportunity"
   for key in (opp,td,fg,empty,other,resolved,unresolved,pts):row[key]=_sum(rows,key)
   row[pp]=_rate(row[pts],row[resolved]);row[tdr]=_rate(row[td],row[opp]);row[fgr]=_rate(row[fg],row[opp]);row[er]=_rate(row[empty],row[opp])
  for suffix in ("","Allowed"):
   n=f"fieldPositionPossessions{suffix}";ytg=f"startYardsToGoalTotal{suffix}";aytg=f"averageStartYardsToGoal{suffix}";own=f"startOwnYardLineTotal{suffix}";aown=f"averageStartOwnYardLine{suffix}";row[n]=_sum(rows,n);row[ytg]=_sum(rows,ytg);row[own]=_sum(rows,own);row[aytg]=_rate(row[ytg],row[n]);row[aown]=_rate(row[own],row[n])
  for key in ("giveaways","interceptionsThrown","fumblesLost","turnoverResolvedPossessions","turnoverUnresolvedPossessions","takeaways","interceptionsMade","fumblesRecovered","takeawayResolvedPossessions","takeawayUnresolvedPossessions"):row[key]=_sum(rows,key)
  row["turnoverMargin"]=row["takeaways"]-row["giveaways"]
  row["tacklesForLoss"]=_sum(rows,"tacklesForLoss");row["tacklesForLossAllowed"]=_sum(rows,"tacklesForLossAllowed")
  for version in ("successDefinitionVersion","explosivenessDefinitionVersion","finishingDrivesDefinitionVersion","fieldPositionDefinitionVersion","turnoversDefinitionVersion","tflDefinitionVersion"):row[version]=next((r.get(version) for r in rows if r.get(version)),None)
  out.append(row)
 return out
def _load_season_games(raw_root,processed_root,season):
 rows=[];payloads=[]
 for st,w in discover_partitions(raw_root,season):
  p=derived_game_partition_dir(processed_root,season,st,w)/"team_games.json"
  if not p.exists():raise FileNotFoundError(f"Derived team-game partition missing: {p}")
  b=p.read_bytes();payloads.append(b);rows.extend(json.loads(b))
 return rows,b"".join(payloads)
def materialize_season(processed_root,raw_root,season,refresh=False):
 rows,source=_load_season_games(raw_root,processed_root,season);target=derived_season_dir(processed_root,season);path=target/"team_seasons.json";manifest=target/"team_seasons.manifest.json";sig=_sha(source)
 if not refresh and path.exists() and manifest.exists():
  m=json.loads(manifest.read_text())
  if m.get("input_sha256")==sig and m.get("season_schema_version")==SEASON_SCHEMA_VERSION:return {**m,"status":"REUSED"}
 out=derive_team_seasons(rows,season);payload=json.dumps(out,ensure_ascii=False,separators=(",",":")).encode();m={"entity":"team_seasons","layer":"derived","season":season,"record_count":len(out),"team_game_count":len(rows),"review_record_count":sum(r['seasonValidationStatus']!='PASS' for r in out),"input_sha256":sig,"output_sha256":_sha(payload),"season_schema_version":SEASON_SCHEMA_VERSION};_atomic(path,payload);_atomic(manifest,json.dumps(m,indent=2,sort_keys=True).encode());return {**m,"status":"WRITTEN"}
def materialize_season_corpus(raw_root,processed_root,seasons,refresh=False):return [materialize_season(processed_root,raw_root,s,refresh) for s in seasons]
def season_corpus_audit(raw_root,processed_root,seasons):
 records=[];game_rows=[]
 for s in seasons:
  records.extend(json.loads((derived_season_dir(processed_root,s)/"team_seasons.json").read_text()));gr,_=_load_season_games(raw_root,processed_root,s);game_rows.extend(gr)
 keys={(r['season'],r['team']) for r in records};expected={(r['season'],r['team']) for r in game_rows};game_counts=defaultdict(int)
 for r in game_rows:game_counts[(r['season'],r['team'])]+=1
 checks={"unique_team_season_rows":len(keys)==len(records),"all_team_games_represented":keys==expected,"games_played_reconciles":all(r['games']==game_counts[(r['season'],r['team'])] for r in records),"offense_defense_possessions_reconcile":_sum(records,'validatedPossessions')==_sum(records,'validatedDefensivePossessions'),"offense_defense_yards_reconcile":_sum(records,'offensiveYards')==_sum(records,'defensiveYardsAllowed'),"success_counts_reconcile_to_games":_sum(records,'successEligiblePlays')==_sum(game_rows,'successEligiblePlays') and _sum(records,'successfulPlays')==_sum(game_rows,'successfulPlays'),"success_offense_defense_reconcile":_sum(records,'successEligiblePlays')==_sum(records,'successEligiblePlaysAllowed') and _sum(records,'successfulPlays')==_sum(records,'successfulPlaysAllowed'),"explosive_counts_reconcile_to_games":_sum(records,'explosiveEligiblePlays')==_sum(game_rows,'explosiveEligiblePlays') and _sum(records,'explosivePlays')==_sum(game_rows,'explosivePlays'),"explosive_offense_defense_reconcile":_sum(records,'explosiveEligiblePlays')==_sum(records,'explosiveEligiblePlaysAllowed') and _sum(records,'explosivePlays')==_sum(records,'explosivePlaysAllowed'),"successful_yards_reconcile_to_games":_sum(records,'successfulPlayYards')==_sum(game_rows,'successfulPlayYards'),"successful_yards_offense_defense_reconcile":_sum(records,'successfulPlayYards')==_sum(records,'successfulPlayYardsAllowed'),"finishing_counts_reconcile_to_games":_sum(records,'scoringOpportunities')==_sum(game_rows,'scoringOpportunities') and _sum(records,'opportunityPoints')==_sum(game_rows,'opportunityPoints'),"finishing_offense_defense_reconcile":_sum(records,'scoringOpportunities')==_sum(records,'scoringOpportunitiesAllowed') and _sum(records,'opportunityPoints')==_sum(records,'opportunityPointsAllowed'),"field_position_counts_reconcile_to_games":_sum(records,'fieldPositionPossessions')==_sum(game_rows,'fieldPositionPossessions') and _sum(records,'startYardsToGoalTotal')==_sum(game_rows,'startYardsToGoalTotal'),"field_position_offense_defense_reconcile":_sum(records,'fieldPositionPossessions')==_sum(records,'fieldPositionPossessionsAllowed') and _sum(records,'startYardsToGoalTotal')==_sum(records,'startYardsToGoalTotalAllowed'),"turnover_counts_reconcile_to_games":_sum(records,'giveaways')==_sum(game_rows,'giveaways') and _sum(records,'takeaways')==_sum(game_rows,'takeaways') and _sum(records,'interceptionsThrown')==_sum(game_rows,'interceptionsThrown') and _sum(records,'fumblesLost')==_sum(game_rows,'fumblesLost'),"turnover_offense_defense_reconcile":_sum(records,'giveaways')==_sum(records,'takeaways') and _sum(records,'interceptionsThrown')==_sum(records,'interceptionsMade') and _sum(records,'fumblesLost')==_sum(records,'fumblesRecovered'),"turnover_margin_sums_zero":_sum(records,'turnoverMargin')==0,"tfl_counts_reconcile_to_games":_sum(records,'tacklesForLoss')==_sum(game_rows,'tacklesForLoss') and _sum(records,'tacklesForLossAllowed')==_sum(game_rows,'tacklesForLossAllowed'),"tfl_offense_defense_reconcile":_sum(records,'tacklesForLoss')==_sum(records,'tacklesForLossAllowed')}
 return {"status":"PASS" if all(checks.values()) else "REVIEW","team_season_rows":len(records),"team_game_rows":len(game_rows),"seasons":len(seasons),"review_rows":sum(r['seasonValidationStatus']!='PASS' for r in records),"success_eligible_plays":_sum(records,'successEligiblePlays'),"successful_plays":_sum(records,'successfulPlays'),"explosive_eligible_plays":_sum(records,'explosiveEligiblePlays'),"explosive_plays":_sum(records,'explosivePlays'),"successful_play_yards":_sum(records,'successfulPlayYards'),"scoring_opportunities":_sum(records,'scoringOpportunities'),"opportunity_points":_sum(records,'opportunityPoints'),"unresolved_point_opportunities":_sum(records,'unresolvedPointOpportunities'),"field_position_possessions":_sum(records,'fieldPositionPossessions'),"giveaways":_sum(records,'giveaways'),"takeaways":_sum(records,'takeaways'),"interceptions":_sum(records,'interceptionsThrown'),"fumbles_lost":_sum(records,'fumblesLost'),"turnover_unresolved_possessions":_sum(records,'turnoverUnresolvedPossessions'),"tackles_for_loss":_sum(records,'tacklesForLoss'),"checks":checks}
def concise_season_audit(r):
 lines=[f"DERIVED TEAM-SEASON CORPUS AUDIT: {r['status']}",f"Seasons: {r['seasons']:,}",f"Team-game rows aggregated: {r['team_game_rows']:,}",f"Team-season rows: {r['team_season_rows']:,}",f"Review rows: {r['review_rows']:,}",f"Success eligible plays: {r['success_eligible_plays']:,}",f"Successful plays: {r['successful_plays']:,}",f"Explosive eligible plays: {r['explosive_eligible_plays']:,}",f"Explosive plays: {r['explosive_plays']:,}",f"Successful-play yards: {r['successful_play_yards']:,.0f}",f"Scoring opportunities: {r['scoring_opportunities']:,}",f"Adjudicated opportunity points: {r['opportunity_points']:,}",f"Unresolved point opportunities: {r['unresolved_point_opportunities']:,}",f"Field-position eligible possessions: {r['field_position_possessions']:,}",f"Giveaways: {r['giveaways']:,}",f"Takeaways: {r['takeaways']:,}",f"Interceptions: {r['interceptions']:,}",f"Fumbles lost: {r['fumbles_lost']:,}",f"Turnover-unresolved possessions: {r['turnover_unresolved_possessions']:,}",f"Tackles for loss: {r['tackles_for_loss']:,}","","Checks:"]+[f"{'PASS' if v else 'FAIL'} {k}" for k,v in r['checks'].items()];return "\n".join(lines)
